// Disposable native fixtures generated by PlaneGcsSymmetricNormalRuntimeTests.
import assert from 'node:assert/strict';
import {mkdir,readFile,writeFile} from 'node:fs/promises';
const {chromium,expect}=await import(process.env.PLAYWRIGHT_MODULE??'playwright/test');
const url=process.env.DXFER_QA_URL, target=new URL(url);
assert.ok(['127.0.0.1','localhost'].includes(target.hostname)||target.origin==='https://dxferdev.sync.harrisonmetals.com'
  &&process.env.DXFER_ALLOW_PUBLIC_DEV==='1'&&process.env.DXFER_EXPECTED_REVISION);
assert.ok(process.env.DXFER_QA_API_KEY&&process.env.DXFER_SYMMETRY_FIXTURES);
const output=process.env.DXFER_SCREENSHOTS??`/tmp/dxfer-symmetry-curves-browser-${Date.now()}`;
await mkdir(output,{recursive:true,mode:0o700});
const decode=text=>{
  const lines=text.trim().split(/\r?\n/);let hex='';
  for(let i=0;i<lines.length;i+=2)if(lines[i].trim()==='310')hex+=lines[i+1].trim();
  assert.ok(hex);return JSON.parse(Buffer.from(hex,'hex'));
};
const contents=d=>({entities:d.entities,constraints:d.constraints,dimensions:d.dimensions});
const near=(a,b)=>assert.ok(Math.abs(a-b)<1e-6,`${a} != ${b}`);
const check=d=>{
  const relations=d.constraints.filter(c=>c.kind==='Symmetric');assert.equal(relations.length,1);assert.equal(relations[0].state,'Satisfied');
  const a=d.entities.find(e=>e.id==='a'),b=d.entities.find(e=>e.id==='b');
  if(a.kind==='spline') {
    for(const field of ['controlPoints','fitPoints']) (a[field]??[]).forEach((p,i)=>{near(p.x,-b[field][i].x);near(p.y,b[field][i].y);});
    for(const field of ['degree','knots','weights']) assert.deepEqual(a[field],b[field]);
  } else {near(a.center.x,-b.center.x);near(a.center.y,b.center.y);}
};
const browser=await chromium.launch({headless:true,executablePath:process.env.DXFER_CHROMIUM});
const results={passed:false,cases:[],errors:[]};let page,failure;
try {
  page=await browser.newPage({viewport:{width:1440,height:1000},extraHTTPHeaders:{'X-DXFER-API-Key':process.env.DXFER_QA_API_KEY}});
  page.setDefaultTimeout(15000);page.on('dialog',d=>d.accept());page.on('pageerror',e=>results.errors.push(e.message));
  await page.goto(url);await page.waitForFunction(()=>document.querySelector('input[type=file]')?._blazorInputFileNextFileId!==undefined);
  results.build=await page.locator('.app-brand').getAttribute('title');
  if(process.env.DXFER_EXPECTED_REVISION)assert.ok(results.build.includes(process.env.DXFER_EXPECTED_REVISION));
  const canvas=page.locator('canvas.drawing-canvas');await expect(canvas).toHaveAttribute('data-solver-engine','PlaneGCS');
  const tool=async name=>{await page.getByRole('button',{name,exact:true}).click();await page.waitForTimeout(150);};
  const menu=async name=>{await tool('Open application menu');await page.getByRole('button',{name:'File',exact:true}).hover();await tool(name);};
  const load=async text=>{
    await canvas.press('Escape');await menu('New drawing');await expect(canvas).toHaveAttribute('data-entity-count','0');
    await page.locator('input[type=file]').setInputFiles({name:'symmetry-curves.dxf',mimeType:'application/dxf',buffer:Buffer.from(text)});
    await expect(canvas).toHaveAttribute('data-entity-count','3');await tool('Fit extents');await canvas.press('Escape');await page.waitForTimeout(350);
  };
  const download=async name=>{
    const pending=page.waitForEvent('download');await menu('Download DXF');const text=await readFile(await(await pending).path(),'utf8');
    await writeFile(`${output}/${name}.dxf`,text);return {text,doc:decode(text)};
  };
  const screen=p=>canvas.evaluate((c,p)=>({x:c.getBoundingClientRect().left+p.x*+c.dataset.scale+ +c.dataset.offsetX,
    y:c.getBoundingClientRect().top-p.y*+c.dataset.scale+ +c.dataset.offsetY}),p);
  await menu('Settings');await page.getByRole('checkbox',{name:'Automatic snap constraints',exact:true}).setChecked(false);await tool('Close settings');
  for(const kind of ['spline','fit','rational','ellipse','round-ellipse','partial-ellipse','polygon'])for(const preselect of [false,true]){
    const name=`${kind}-${preselect?'preselect':'tool-first'}`;
    await load(await readFile(`${process.env.DXFER_SYMMETRY_FIXTURES}/${kind}-before.dxf`,'utf8'));
    const before=await download(`${name}-before`);
    const picks=JSON.parse(await readFile(`${process.env.DXFER_SYMMETRY_FIXTURES}/${kind}-picks.json`,'utf8'));
    if(!preselect)await tool('Symmetric');
    for(let i=0;i<picks.length;i++){
      const p=await screen(picks[i]);await page.mouse.move(p.x,p.y);
      if(preselect&&i>0)await page.keyboard.down('Shift');
      try{await page.mouse.click(p.x,p.y);}finally{if(preselect&&i>0)await page.keyboard.up('Shift');}
      await page.waitForTimeout(180);
    }
    if(preselect)await tool('Symmetric');await page.waitForTimeout(300);await canvas.press('Escape');
    const saved=await download(`${name}-solved`);check(saved.doc);
    await tool('Undo');assert.deepEqual(contents((await download(`${name}-undo`)).doc),contents(before.doc));
    await tool('Redo');assert.deepEqual(contents((await download(`${name}-redo`)).doc),contents(saved.doc));
    await load(saved.text);const reopened=await download(`${name}-reopened`);check(reopened.doc);
    assert.deepEqual(contents(reopened.doc),contents(saved.doc));
    const source=reopened.doc.entities.find(e=>e.id==='a');
    if(source.kind==='spline') {
      const endpoint=await screen(source.fitPoints?.length?source.fitPoints[0]:source.controlPoints[0]);
      await page.mouse.click(endpoint.x,endpoint.y);await page.waitForTimeout(180);
    }
    const start=source.kind==='spline'?(source.fitPoints?.length?source.fitPoints[1]:source.controlPoints[1]):source.center;
    const from=await screen(start),to=await screen({x:start.x-.5,y:start.y+.5});
    await page.mouse.move(from.x,from.y);await page.mouse.down();await page.mouse.move(to.x,to.y,{steps:12});
    await page.waitForTimeout(150);await page.mouse.up();await page.waitForTimeout(300);
    const edited=await download(`${name}-edited`);check(edited.doc);assert.notDeepEqual(edited.doc.entities,reopened.doc.entities);
    await tool('Undo');assert.deepEqual(contents((await download(`${name}-edit-undo`)).doc),contents(reopened.doc));
    await tool('Redo');check((await download(`${name}-edit-redo`)).doc);
    await page.screenshot({path:`${output}/${name}.png`});results.cases.push(name);console.log(`PASS ${name}`);
  }
  assert.deepEqual(results.errors,[]);results.passed=true;
}catch(error){failure=error;results.failure=error.stack;await page?.screenshot({path:`${output}/failure.png`}).catch(()=>{});}
finally{await writeFile(`${output}/results.json`,JSON.stringify(results,null,2));await browser.close();}
if(failure)throw failure;console.log(JSON.stringify(results));
